"import sqlite3
import re

db_path = r'C:\Users\renu5\.gemini\antigravity\conversations\1682ac12-05ba-422a-a04c-f2d378a84e1d.db'
conn = sqlite3.connect(db_path)
c = conn.cursor()

c.execute("SELECT name FROM sqlite_master WHERE type='table';")
tables = c.fetchall()

search_strings = [b'133e05e6', b'Clone', b'Researching']

found = False
for t in tables:
    table_name = t[0]
    try:
        c.execute(f"SELECT * FROM {table_name}")
        rows = c.fetchall()
        for i, row in enumerate(rows):
            for j, col in enumerate(row):
                if type(col) is bytes:
                    for s in search_strings:
                        if s.lower() in col.lower():
                            print(f"Found {s} in {table_name} row {i} col {j}")
                            # extract surrounding context
                            idx = col.lower().find(s.lower())
                            start = max(0, idx - 100)
                            end = min(len(col), idx + 100)
                            context = col[start:end].decode('utf-8', errors='ignore')
                            print(f"Context: {context}")
                            found = True
                elif type(col) is str:
                    for s in search_strings:
                        s_str = s.decode()
                        if s_str.lower() in col.lower():
                            print(f"Found {s_str} in {table_name} row {i} col {j}")
                            idx = col.lower().find(s_str.lower())
                            start = max(0, idx - 100)
                            end = min(len(col), idx + 100)
                            context = col[start:end]
                            print(f"Context: {context}")
                            found = True
    except Exception as e:
        print(f"Error reading table {table_name}: {e}")

if not found:
    print("Not found in any table.")
